-- =============================================================
-- TrueBuddy - 音色库表 avatar_voice
-- 对应讲课模块 tb-module-lecture（PPT 数字人设置）
-- 说明：
--   1. 内置音色 creator 为空，所有登录用户可见；复刻音色 creator 为创建者，仅本人可见；
--   2. source：1=内置（cosyvoice-v3-flash 系统音色），2=复刻（DashScope 声音复刻返回的 voice_id）；
--   3. audio_preview_url 为内置音色的官方试听地址；复刻音色看 sample_audio_url / sample_file_id；
--   4. 软删用 deleted 布尔列（与 lecture_meeting 一致）；creator / updater 为逻辑外键。
-- =============================================================

CREATE TABLE IF NOT EXISTS avatar_voice (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY, -- 主键（自增）
    voice_code        VARCHAR(128) NOT NULL,                   -- 音色编码（唯一），如 longxiaochun_v3
    name              VARCHAR(50)  NOT NULL,                   -- 音色名称
    trait             VARCHAR(100),                            -- 特征描述
    age               VARCHAR(50),                             -- 适用年龄段
    language          VARCHAR(100),                            -- 支持语言
    category          VARCHAR(50)  NOT NULL,                   -- 分类：社交陪伴/语音助手/客服/有声书/诗词朗诵/新闻播报/短视频配音/方言/直播带货/我的复刻
    gender            VARCHAR(20)  NOT NULL DEFAULT 'female',  -- 性别：male / female
    source            SMALLINT     NOT NULL DEFAULT 1,         -- 来源：1=内置，2=复刻
    tts_model         VARCHAR(50),                             -- 复刻音色绑定的 TTS 模型；内置为空时用全局配置
    audio_preview_url VARCHAR(500),                            -- 试听音频 URL（内置音色的官方示例）
    sample_file_id    BIGINT,                                  -- 复刻样本文件（infra_file.id，可空）
    sample_audio_url  VARCHAR(500),                            -- 复刻样本的公网 URL（粘贴 URL 时记录）
    create_time       TIMESTAMP    NOT NULL DEFAULT now(),     -- 创建时间
    update_time       TIMESTAMP    NOT NULL DEFAULT now(),     -- 更新时间
    creator           BIGINT,                                  -- 创建人 id（内置音色为空）
    updater           BIGINT,                                  -- 更新人 id
    deleted           BOOLEAN      NOT NULL DEFAULT FALSE,     -- 是否删除：false=否，true=是
    PRIMARY KEY (id)
);

COMMENT ON TABLE  avatar_voice IS '音色库（cosyvoice-v3-flash 内置音色 + 用户复刻音色）';
COMMENT ON COLUMN avatar_voice.voice_code IS '音色编码（唯一），内置如 longxiaochun_v3，复刻为 DashScope 返回的 voice_id';
COMMENT ON COLUMN avatar_voice.name IS '音色名称';
COMMENT ON COLUMN avatar_voice.trait IS '特征描述';
COMMENT ON COLUMN avatar_voice.age IS '适用年龄段';
COMMENT ON COLUMN avatar_voice.language IS '支持语言';
COMMENT ON COLUMN avatar_voice.category IS '分类；复刻音色固定为「我的复刻」';
COMMENT ON COLUMN avatar_voice.gender IS '性别：male / female';
COMMENT ON COLUMN avatar_voice.source IS '来源：1=内置，2=复刻';
COMMENT ON COLUMN avatar_voice.tts_model IS '复刻音色绑定的 TTS 模型；为空时使用 tb.lecture.digital-human.tts-model';
COMMENT ON COLUMN avatar_voice.audio_preview_url IS '试听音频 URL（内置音色的官方示例）';
COMMENT ON COLUMN avatar_voice.sample_file_id IS '复刻样本文件 id（infra_file.id）';
COMMENT ON COLUMN avatar_voice.sample_audio_url IS '复刻样本的公网音频 URL';

CREATE UNIQUE INDEX IF NOT EXISTS uk_avatar_voice_code ON avatar_voice (voice_code);
CREATE INDEX IF NOT EXISTS idx_avatar_voice_category ON avatar_voice (category);
CREATE INDEX IF NOT EXISTS idx_avatar_voice_gender ON avatar_voice (gender);
CREATE INDEX IF NOT EXISTS idx_avatar_voice_creator ON avatar_voice (creator) WHERE deleted = FALSE;

